"""Is the non-Jacobian E1 kernel in degree d generated by the degree-7 elements?  Test
   K_d  subset  D7*S_{d-7} + D7Y*S_{d-7} + J_d   (mod p), per parity; report dimensions."""
import sys, time, json
sys.path.insert(0, '/tmp/hodge/results/symmetric-sextic-residual')
import numpy as np
from flint import nmod_mat
import w2x_lib as L
from hodge import core
F, A, q = L.load()
p = int(sys.argv[1]) if len(sys.argv) > 1 else L.P1
degs = [int(x) for x in sys.argv[2].split(',')] if len(sys.argv) > 2 else [8, 9]
mul, add, sub, sc, pw = core.mul, core.add, core.sub, core.scale, core.power
X, Y = L.X, L.Y
QX, QY, e1X, e1Y, e3X, e3Y = L.e_k(X,2), L.e_k(Y,2), L.e_k(X,1), L.e_k(Y,1), L.e_k(X,3), L.e_k(Y,3)
D7 = core.reduce_mod(mul(L.dlt(X), sub(pw(QX,2), sc(mul(e1X,e3X),2))), p)
D7Y = core.reduce_mod(mul(L.dlt(Y), sub(pw(QY,2), sc(mul(e1Y,e3Y),2))), p)
for d in degs:
    for pD in (0, 1):
        t0 = time.time()
        fam = L.E1Family(F, A, d, pD, p, verbose=True)
        red = L.Reducer(F, d, pD, p, verbose=True)
        Dpolys = [fam.pair(fam.K[i])[0] for i in range(fam.dimK)]
        CK = red.coords(Dpolys)
        rkK = nmod_mat(CK.shape[0], CK.shape[1], CK.ravel().tolist(), p).rank()
        gens = []
        for m in core.monomials(d - 7, pD): gens.append(core.shift(D7, m, 1, p))        # D7 even
        for m in core.monomials(d - 7, (pD + 1) % 2): gens.append(core.shift(D7Y, m, 1, p))  # D7Y odd
        CG = red.coords(gens) if gens else np.zeros((0, CK.shape[1]), dtype=np.int64)
        rkG = nmod_mat(CG.shape[0], CG.shape[1], CG.ravel().tolist(), p).rank() if gens else 0
        both = np.concatenate([CK, CG], axis=0)
        rkB = nmod_mat(both.shape[0], both.shape[1], both.ravel().tolist(), p).rank()
        rec = {'exp': 'kernel-structure', 'd': d, 'pD': pD, 'prime': p, 'ker_R': fam.ker_R, 'rank_kernel_in_R': rkK, 'rank_D7multiples_in_R': rkG,
               'rank_union': rkB, 'kernel_generated_by_D7_D7Y': bool(rkB == rkG and rkK == rkG), 'new_directions': int(rkB - rkG), 'seconds': round(time.time() - t0, 1), 'job': 'kernel-structure'}
        L.log(rec); print(json.dumps(rec), flush=True)
